  JSONObject unit=new JSONObject().put("unit_id","fixture:0").put("source_id","fixture").put("text","无信息背景杂音");JSONObject p=new JSONObject().put("content_kind","noise").put("unit_ids",new JSONArray().put("fixture:0")).put("units",new JSONArray().put(unit)).put("text","无信息背景杂音");JSONObject extraction=new JSONObject().put("facts",new JSONArray()).put("paragraphs",new JSONArray().put(p));JSONObject provider=new JSONObject().put("model","synthetic");JSONObject d=new JSONObject().put("index",0).put("action","HIDE").put("reason","上下文没有独有内容").put("context_reviewed",true).put("unique_information",false);JSONObject response=new JSONObject().put("decisions",new JSONArray().put(d));ContentFilter.apply(extraction,response,provider);check(p.getJSONObject("filter_decision").getString("action").equals("HIDE"),"noise can be hidden after context review");
